using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Splines;using TutorialFramework;
public static class BatchMultiGeometry{
 [Serializable]class Shape{public string name;public Vector3[] controls;public float radius;}
 [Serializable]class Set{public int seed;public Shape[] shapes;}
 static Shape Read(FreeLabWire w){var c=w.GetComponentInChildren<SplineContainer>(true);var s=c.Spline;var list=new List<Vector3>();for(int i=0;i<s.Count-1;i++){var a=s[i];var b=s[i+1];var p=c.transform.TransformPoint((Vector3)a.Position);var q=c.transform.TransformPoint((Vector3)b.Position);list.AddRange(new[]{p,p+c.transform.TransformVector((Vector3)Unity.Mathematics.math.rotate(a.Rotation,a.TangentOut)),q+c.transform.TransformVector((Vector3)Unity.Mathematics.math.rotate(b.Rotation,b.TangentIn)),q});}return new Shape{name=w.name,controls=list.ToArray(),radius=c.GetComponent<SplineExtrude>().Radius*Mathf.Abs(c.transform.lossyScale.x)};}
 public static void Run(FreeLabWindController wind){var create=typeof(FreeLabManager).GetMethod("CreateConnection",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);var sets=new List<Set>();File.WriteAllText("Temp/V12BatchNext/multi-runtime.jsonl","");for(int seed=0;seed<8;seed++){foreach(var w in wind.lab.Connections.ToArray())w.RemoveFromFreeLab();var rand=new System.Random(seed);foreach(var d in wind.definitions.OrderBy(d=>rand.Next())){if(wind.lab.HasConnection(d.endpointA,d.endpointB))continue;create.Invoke(wind.lab,new object[]{d.endpointA,d.endpointB});}File.AppendAllText("Temp/V12BatchNext/multi-runtime.jsonl",JsonUtility.ToJson(new Set{seed=seed,shapes=wind.lab.Connections.Select(Read).ToArray()})+"\n");}foreach(var w in wind.lab.Connections.ToArray())w.RemoveFromFreeLab();}
}
